// array for output 
let outputArray = [];

// battery to target
const target = `marstek_m${msg.battery_index}`;

// HBC+ phase guard (2026-11-14): when control goes back to the Marstek firmware (RS485 'disable'),
// only ONE battery per shared phase may do that (the lowest M-number on the phase). Its partner
// stays under RS485 control with forcible 'stop', so two batteries in firmware mode can never
// overload the phase fuse. Only on Enforce; Off / Monitor / any error -> unchanged.
let hbcPlusStandby = false;
try {
    const ha = global.get('homeassistant');
    let states = null;
    if (ha && typeof ha === 'object') {
        const servers = Object.values(ha).filter(s => s && s.states && typeof s.states === 'object');
        const srv = servers.find(s => s.isConnected !== false) || servers[0];
        if (srv) states = srv.states;
    }
    const raw = (id) => (states && states[id] ? states[id].state : undefined);
    const usable = (v) => v !== undefined && v !== null && v !== '' && v !== 'unknown' && v !== 'unavailable';
    const num = (id, def) => { const v = raw(id); const n = Number(v); return usable(v) && Number.isFinite(n) ? n : def; };
    const str = (id, def) => { const v = raw(id); return usable(v) ? String(v) : def; };
    if (msg.rs485 === 'disable' && str('input_select.house_battery_phase_guard_mode', 'Off') === 'Enforce') {
        const ph = str(`input_select.${target}_phase`, '');
        if (['L1', 'L2', 'L3'].includes(ph)) {
            const count = num('input_number.house_battery_count', 0);
            const same = [];
            for (let i = 1; i <= count; i++) if (str(`input_select.marstek_m${i}_phase`, '') === ph) same.push(i);
            hbcPlusStandby = same.length > 1 && same[0] !== Number(msg.battery_index);
        }
    }
} catch (e) {
    node.warn(`HBC+ phase check failed, battery handled as before: ${e && e.message}`);
}

// Set | work mode
const workModeAction = {
    "action": "select.select_option",
    "target": {
        "entity_id": [`select.${target}_user_work_mode`]
    },
    "data": {
         "option": String(msg.work_mode)
    }
};
// Add to output array. Set null for no action.
outputArray.push(msg.work_mode && !hbcPlusStandby ? { payload: workModeAction, topic:"user_work_mode"}: null);

// Set | rs485
const rs485Action = {
    "action": "select.select_option",
    "target": {
        "entity_id": [`select.${target}_rs485_control_mode`]
    },
    "data": {
         "option": String(msg.rs485)
    }
};
// Add to output array. Set null for no action.
if (hbcPlusStandby) {
    // HBC+: partner on a shared phase stays under RS485 control and stopped (two messages, same output)
    const keepRs485 = { "action": "select.select_option", "target": { "entity_id": [`select.${target}_rs485_control_mode`] }, "data": { "option": "enable" } };
    const stopAction = { "action": "select.select_option", "target": { "entity_id": [`select.${target}_forcible_charge_discharge`] }, "data": { "option": "stop" } };
    outputArray.push([{ payload: keepRs485, topic: "rs485_control_mode" }, { payload: stopAction, topic: "forcible_charge_discharge" }]);
    node.status({ fill: "yellow", shape: "dot", text: `${target}: HBC+ phase partner kept on RS485 + stop` });
} else {
    outputArray.push(msg.rs485 ? { payload: rs485Action, topic: "rs485_control_mode" } : null);
}

// Store calls in msg to allow checking of loop results
msg.loop_result = { target, workModeAction, rs485Action };

// Return msg as third output
outputArray.push(msg);

// Outputs
return outputArray;

// loop through the number of batteries set by the user
msg.battery_index = 1; // base-1

// configurables
let workMode = null; // manual, anti-feed, ai, null = don't set or alter this setting
let rs485 = null;  // enable, disable, null = don't set or alter this setting

// mode select
switch (msg.marstek_master_battery_mode) {
    case "Manual control":
        workMode = "manual";
        rs485 = "disable";
        break;
    case "Marstek control":
        // the user should select a work mode via the Marstek App or via select.marstek_mX_user_work_mode
        rs485 = "disable";
        break;
    case "Full control":
        rs485 = "enable";
        break;
    default:
        node.status({fill:"red",shape:"ring",text:`Unhandled mode: ${msg.marstek_master_battery_mode}`});
        return null; // stop flow
}

// Continue
msg.work_mode = workMode;
msg.rs485 = rs485;
return msg;

// Step index down
msg.battery_index += 1;

// Continue
return msg;
